window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a2f0aeaaa0dede65"]={"versions": [{"id": "FIG-a2f0aeaaa0dede65", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Interaktionsablaufs bei der Aktivierung der Erfassung von Sende-Zeitstempeln (Egress Time Stamping) im AUTOSAR Classic Platform Kommunikations- und Zeitsynchronisations-Stack. Es beschreibt den vertikalen Kontrollfluss zwischen der Time-Synchronization-Schicht und dem Ethernet-Treiber über das Ethernet-Interface.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei BSW-Module als Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>EthTSyn</code> (Stereotyp <code>«module»</code>): Synchronisationsmodul für Ethernet (Time Synchronization over Ethernet).\n</li><li><code>EthIf</code> (Stereotyp <code>«module»</code>): Ethernet Interface zur Abstraktion der darunterliegenden Hardwaretreiber.\n</li><li><code>Eth</code> (Stereotyp <code>«module»</code>): Ethernet Controller Driver.\n</li></ul>\n<p class=\"fig-p\">Beteiligte Schnittstellenaufrufe:</p>\n<ul class=\"fig-list\"><li><code>EthIf_EnableEgressTimeStamp(uint8, uint8)</code>: Synchroner Aufruf von <code>EthTSyn</code> an <code>EthIf</code>.\n</li><li><code>Eth_EnableEgressTimeStamp(uint8, uint8)</code>: Synchroner Weiterleitungsaufruf von <code>EthIf</code> an den Treiber <code>Eth</code>.\n</li><li>Zugehörige gestrichelte Rückkehrpfeile (Return Messages) nach Abschluss der Funktionsausführung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>EthTSyn</code> führt eine interne Prüfung unter der Bedingung <code>[EthTSynHardwareTimestamp == TRUE]</code> aus (dargestellt als Selbstaufruf/Reflexivnachricht).\n</li><li>Bei erfüllter Bedingung ruft <code>EthTSyn</code> synchron <code>EthIf_EnableEgressTimeStamp(uint8, uint8)</code> auf <code>EthIf</code> auf; die Ausführungsüberlagerung (Activation Bar) auf <code>EthIf</code> wird aktiv.\n</li><li><code>EthIf</code> delegiert den Aufruf synchron weiter an den Controller-Treiber <code>Eth</code> via <code>Eth_EnableEgressTimeStamp(uint8, uint8)</code>.\n</li><li>Nach Abarbeitung in <code>Eth</code> erfolgt die Rückkehr zu <code>EthIf</code>.\n</li><li>Abschließend kehrt <code>EthIf</code> zu <code>EthTSyn</code> zurück, womit die Aktivierung des Egress-Timestamps abgeschlossen ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Ausführung der Treiber- und Schnittstellenaufrufe zur Hardware-Zeitstempelerfassung ist strikt an den Präprozessor- bzw. Konfigurationsschalter <code>EthTSynHardwareTimestamp</code> gebunden. Beide APIs verwenden untypisierte Indexwerte vom Basistyp <code>uint8</code> zur Adressierung von Controller und Puffer. Implementierer müssen sicherstellen, dass die Aufrufkette synchron abläuft und die Rückkehrwerte die erfolgreiche Konfiguration im Treiber signalisieren.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a3835801ed9162c8", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Interaktionsablaufs bei der Aktivierung der Erfassung von Sende-Zeitstempeln (Egress Time Stamping) im AUTOSAR Classic Platform Kommunikations- und Zeitsynchronisations-Stack. Es beschreibt den vertikalen Kontrollfluss zwischen der Time-Synchronization-Schicht und dem Ethernet-Treiber über das Ethernet-Interface.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei BSW-Module als Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>EthTSyn</code>: Synchronisationsmodul für Ethernet (Time Synchronization over Ethernet).\n</li><li><code>EthIf</code>: Ethernet Interface zur Abstraktion der Ethernet-Treiber.\n</li><li><code>Eth</code>: Ethernet Controller Driver.\n</li></ul>\n<p class=\"fig-p\">Beteiligte Schnittstellenaufrufe:</p>\n<ul class=\"fig-list\"><li><code>EthIf_EnableEgressTimeStamp(CtrlIdx :uint8, BufIdx :Eth_BufIdxType) :Std_ReturnType</code>: Synchroner Aufruf von <code>EthTSyn</code> an <code>EthIf</code>.\n</li><li><code>Eth_EnableEgressTimestamp(CtrlIdx :uint8, BufIdx :Eth_BufIdxType) :Std_ReturnType</code>: Synchroner Treiberaufruf von <code>EthIf</code> an <code>Eth</code>.\n</li><li>Zugehörige gestrichelte Rückkehrpfeile zur Bestätigung der Aufrufe.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>EthTSyn</code> führt eine interne Prüfung unter der Bedingung <code>[EthTSynHardwareTimestampSupport == TRUE]</code> aus (dargestellt als Selbstaufruf/Reflexivnachricht).\n</li><li>Bei erfüllter Bedingung ruft <code>EthTSyn</code> synchron <code>EthIf_EnableEgressTimeStamp(CtrlIdx :uint8, BufIdx :Eth_BufIdxType) :Std_ReturnType</code> auf <code>EthIf</code> auf.\n</li><li><code>EthIf</code> leitet den Aufruf synchron weiter an <code>Eth</code> via <code>Eth_EnableEgressTimestamp(CtrlIdx :uint8, BufIdx :Eth_BufIdxType) :Std_ReturnType</code>.\n</li><li>Nach Abschluss der Operation in <code>Eth</code> kehrt der Kontrollfluss mit dem Rückgabewert zu <code>EthIf</code> zurück.\n</li><li><code>EthIf</code> gibt den Kontrollfluss und das Ergebnis an <code>EthTSyn</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Funktionalität ist über den Konfigurationsparameter <code>EthTSynHardwareTimestampSupport</code> geschützt. Die Schnittstellen sind typisiert spezifiziert: Der Controller-Index wird als <code>CtrlIdx :uint8</code> übergeben, der Puffer-Index als formaler AUTOSAR-Typ <code>BufIdx :Eth_BufIdxType</code>, und beide Funktionen liefern <code>Std_ReturnType</code> zur Fehlerprüfung zurück. Zu beachten ist die unterschiedliche Binnenmajuskel-Schreibweise des Bezeichners (<code>TimeStamp</code> in <code>EthIf</code> vs. <code>Timestamp</code> in <code>Eth</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-bf2b6d6ad5dc2021", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Interaktionsablaufs bei der Aktivierung der Erfassung von Sende-Zeitstempeln (Egress Time Stamping) im AUTOSAR Classic Platform Kommunikations- und Zeitsynchronisations-Stack. Es beschreibt den vertikalen Kontrollfluss zwischen der Time-Synchronization-Schicht und dem Ethernet-Treiber über das Ethernet-Interface.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei BSW-Module als Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>EthTSyn</code>: Synchronisationsmodul für Ethernet (Time Synchronization over Ethernet).\n</li><li><code>EthIf</code>: Ethernet Interface zur Abstraktion der Ethernet-Treiber.\n</li><li><code>Eth</code>: Ethernet Controller Driver.\n</li></ul>\n<p class=\"fig-p\">Beteiligte Schnittstellenaufrufe:</p>\n<ul class=\"fig-list\"><li><code>EthIf_EnableEgressTimeStamp(CtrlIdx :uint8, BufIdx :Eth_BufIdxType) :Std_ReturnType</code>: Synchroner Aufruf von <code>EthTSyn</code> an <code>EthIf</code>.\n</li><li><code>Eth_EnableEgressTimestamp(CtrlIdx :uint8, BufIdx :Eth_BufIdxType) :Std_ReturnType</code>: Synchroner Treiberaufruf von <code>EthIf</code> an <code>Eth</code>.\n</li><li>Zugehörige gestrichelte Rückkehrpfeile zur Bestätigung der Aufrufe.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>EthTSyn</code> führt eine interne Prüfung unter der Bedingung <code>[EthTSynHardwareTimestampSupport == TRUE]</code> aus (dargestellt als Selbstaufruf/Reflexivnachricht).\n</li><li>Bei erfüllter Bedingung ruft <code>EthTSyn</code> synchron <code>EthIf_EnableEgressTimeStamp(CtrlIdx :uint8, BufIdx :Eth_BufIdxType) :Std_ReturnType</code> auf <code>EthIf</code> auf.\n</li><li><code>EthIf</code> leitet den Aufruf synchron weiter an <code>Eth</code> via <code>Eth_EnableEgressTimestamp(CtrlIdx :uint8, BufIdx :Eth_BufIdxType) :Std_ReturnType</code>.\n</li><li>Nach Abschluss der Operation in <code>Eth</code> kehrt der Kontrollfluss mit dem Rückgabewert zu <code>EthIf</code> zurück.\n</li><li><code>EthIf</code> gibt den Kontrollfluss und das Ergebnis an <code>EthTSyn</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Funktionalität ist über den Konfigurationsparameter <code>EthTSynHardwareTimestampSupport</code> geschützt. Die Schnittstellen sind typisiert spezifiziert: Der Controller-Index wird als <code>CtrlIdx :uint8</code> übergeben, der Puffer-Index als formaler AUTOSAR-Typ <code>BufIdx :Eth_BufIdxType</code>, und beide Funktionen liefern <code>Std_ReturnType</code> zur Fehlerprüfung zurück. Zu beachten ist die unterschiedliche Binnenmajuskel-Schreibweise des Bezeichners (<code>TimeStamp</code> in <code>EthIf</code> vs. <code>Timestamp</code> in <code>Eth</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a741cdd77deb4e94", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Interaktionsablaufs bei der Aktivierung der Erfassung von Sende-Zeitstempeln (Egress Time Stamping) im AUTOSAR Classic Platform Kommunikations- und Zeitsynchronisations-Stack. Es beschreibt den vertikalen Kontrollfluss zwischen der Time-Synchronization-Schicht und dem Ethernet-Treiber über das Ethernet-Interface.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei BSW-Module als Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>EthTSyn</code>: Synchronisationsmodul für Ethernet (Time Synchronization over Ethernet).\n</li><li><code>EthIf</code>: Ethernet Interface zur Abstraktion der Ethernet-Treiber.\n</li><li><code>Eth</code>: Ethernet Controller Driver.\n</li></ul>\n<p class=\"fig-p\">Beteiligte Schnittstellenaufrufe:</p>\n<ul class=\"fig-list\"><li><code>EthIf_EnableEgressTimeStamp(CtrlIdx :uint8, BufIdx :Eth_BufIdxType) :Std_ReturnType</code>: Synchroner Aufruf von <code>EthTSyn</code> an <code>EthIf</code>.\n</li><li><code>Eth_EnableEgressTimestamp(CtrlIdx :uint8, BufIdx :Eth_BufIdxType) :Std_ReturnType</code>: Synchroner Treiberaufruf von <code>EthIf</code> an <code>Eth</code>.\n</li><li>Zugehörige gestrichelte Rückkehrpfeile zur Bestätigung der Aufrufe.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>EthTSyn</code> führt eine interne Prüfung unter der Bedingung <code>[EthTSynHardwareTimestampSupport == TRUE]</code> aus (dargestellt als Selbstaufruf/Reflexivnachricht).\n</li><li>Bei erfüllter Bedingung ruft <code>EthTSyn</code> synchron <code>EthIf_EnableEgressTimeStamp(CtrlIdx :uint8, BufIdx :Eth_BufIdxType) :Std_ReturnType</code> auf <code>EthIf</code> auf.\n</li><li><code>EthIf</code> leitet den Aufruf synchron weiter an <code>Eth</code> via <code>Eth_EnableEgressTimestamp(CtrlIdx :uint8, BufIdx :Eth_BufIdxType) :Std_ReturnType</code>.\n</li><li>Nach Abschluss der Operation in <code>Eth</code> kehrt der Kontrollfluss mit dem Rückgabewert zu <code>EthIf</code> zurück.\n</li><li><code>EthIf</code> gibt den Kontrollfluss und das Ergebnis an <code>EthTSyn</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Funktionalität ist über den Konfigurationsparameter <code>EthTSynHardwareTimestampSupport</code> geschützt. Die Schnittstellen sind typisiert spezifiziert: Der Controller-Index wird als <code>CtrlIdx :uint8</code> übergeben, der Puffer-Index als formaler AUTOSAR-Typ <code>BufIdx :Eth_BufIdxType</code>, und beide Funktionen liefern <code>Std_ReturnType</code> zur Fehlerprüfung zurück. Zu beachten ist die unterschiedliche Binnenmajuskel-Schreibweise des Bezeichners (<code>TimeStamp</code> in <code>EthIf</code> vs. <code>Timestamp</code> in <code>Eth</code>).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-a2f0aeaaa0dede65", "to": "FIG-a3835801ed9162c8", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Wegfall des Stereotyps <code>«module»</code> über den Lebenslinien-Köpfen <code>EthTSyn</code>, <code>EthIf</code> und <code>Eth</code>.\n</li><li>Bedingung (Guard): Umbenennung des Konfigurationsparameters von <code>EthTSynHardwareTimestamp == TRUE</code> zu <code>EthTSynHardwareTimestampSupport == TRUE</code>.\n</li><li>Funktionssignatur <code>EthIf_EnableEgressTimeStamp</code>: Hinzufügen von Parameternamen, Typdefinitionen und Rückgabetyp (<code>(CtrlIdx :uint8, BufIdx :Eth_BufIdxType) :Std_ReturnType</code> statt <code>(uint8, uint8)</code>).\n</li><li>Funktionssignatur <code>Eth_EnableEgressTimestamp</code>: Hinzufügen von Parameternamen, Typdefinitionen und Rückgabetyp (<code>(CtrlIdx :uint8, BufIdx :Eth_BufIdxType) :Std_ReturnType</code> statt <code>(uint8, uint8)</code>) sowie typografische Änderung von CamelCase <code>TimeStamp</code> zu <code>Timestamp</code>.\n</li></ul>"}, {"from": "FIG-a3835801ed9162c8", "to": "FIG-bf2b6d6ad5dc2021", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bf2b6d6ad5dc2021", "to": "FIG-a741cdd77deb4e94", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
